def transform(g):
    H,W=len(g),len(g[0])
    bc=g[0][0]
    half=W//2
    borders=[r for r in range(H) if all(g[r][c]==bc for c in range(half))]
    bands=[(borders[i]+1,borders[i+1]) for i in range(len(borders)-1)]
    bcols=[c for c in range(half) if all(g[r][c]==bc for r in range(H))]
    ci0,ci1=bcols[0]+1,bcols[-1]
    shapes={}
    for r in range(H):
        for c in range(half,W):
            v=g[r][c]
            if v: shapes.setdefault(v,set()).add((r,c))
    snorms={v:norm(s) for v,s in shapes.items()}
    out=[row[:half] for row in g]
    for (r0,r1) in bands:
        shape={(r-r0,c-ci0) for r in range(r0,r1) for c in range(ci0,ci1) if g[r][c]==bc}
        comp=[(r,c) for r in range(r1-r0) for c in range(ci1-ci0) if (r,c) not in shape]
        cn=norm(comp)
        col=[v for v,s in snorms.items() if s==cn][0]
        for (r,c) in comp: out[r0+r][ci0+c]=col
    return out

